DECLARE client uuid:=gen_random_uuid();partner uuid:=gen_random_uuid();service uuid:=gen_random_uuid();app uuid;offer uuid;version text;offer_version text;claim uuid;claim_version text;late_app uuid:=gen_random_uuid();qa_contact uuid:=gen_random_uuid();auth uuid:=gen_random_uuid();request uuid:=gen_random_uuid();payload jsonb;r jsonb;replay jsonb;n integer;recorded record;
 client_hash text:=encode(digest(gen_random_uuid()::text,'sha256'),'hex');partner_hash text:=encode(digest(gen_random_uuid()::text,'sha256'),'hex');
BEGIN
 INSERT INTO public.client_profiles(id,display_name,contact) VALUES(client,'QA service client','test-only');
 INSERT INTO public.partners(id,public_name,status) VALUES(partner,'QA service partner','ACTIVE');
 INSERT INTO public.catalog_items(id,public_id,title,entity_type,booking_capacity,owner_partner_id,availability_status,publication_status,moderation_status,client_price_thb) VALUES(service,'QA-'||service,'QA service execution','SERVICE',1,partner,'AVAILABLE','PUBLISHED','APPROVED',1000);
 PERFORM pcs.portal_admin_action('issue-access',jsonb_build_object('role','CLIENT','profile_id',client,'hash',client_hash));
 PERFORM pcs.portal_admin_action('issue-access',jsonb_build_object('role','PARTNER','profile_id',partner,'hash',partner_hash));
 r:=pcs.portal_action(client_hash,'request',gen_random_uuid(),'{"need":"QA service execution"}');app:=(r->>'application_id')::uuid;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;PERFORM pcs.portal_admin_action('assign-partner',jsonb_build_object('application_id',app,'expected_version',version,'partner_id',partner));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 r:=pcs.portal_action(partner_hash,'submit-offer',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'price','1000','deposit','0','terms','QA service terms','catalog_item_id',service,'start_date','2117-01-10','end_date','2117-01-12','booking_quantity','1'));offer:=(r->>'offer_id')::uuid;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;SELECT updated_at::text INTO offer_version FROM public.pcs_partner_offers WHERE id=offer;
 PERFORM pcs.portal_admin_action('review-offer',jsonb_build_object('application_id',app,'expected_version',version,'offer_id',offer,'offer_version',offer_version,'decision','APPROVED'));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;PERFORM pcs.portal_action(client_hash,'select-offer',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'offer_id',offer));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;PERFORM pcs.portal_action(partner_hash,'confirm',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;PERFORM pcs.portal_action(client_hash,'confirm',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version));
 INSERT INTO neon_auth."user"(id,name,email,"emailVerified","createdAt","updatedAt",banned) VALUES(auth,'QA execution staff','qa-execution-'||auth||'@example.invalid',false,now(),now(),false);
 PERFORM pcs.staff_manage(auth,'AUDITOR_READONLY',true);
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 payload:=jsonb_build_object('application_id',app,'expected_version',version,'phase','STARTED','note','Synthetic operator checked start','request_id',request,'confirmed','true');
 BEGIN PERFORM pcs.staff_workflow_action(auth,'service-phase',payload);RAISE EXCEPTION 'QA readonly can execute';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM pcs.portal_admin_action('service-phase',payload||'{"confirmed":"false"}');RAISE EXCEPTION 'QA fact without confirmation';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM pcs.portal_admin_action('service-phase',payload||'{"phase":"COMPLETED"}');RAISE EXCEPTION 'QA complete before start';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE public.applications SET operational_status='COMPLETED' WHERE id=app;RAISE EXCEPTION 'QA generic editor bypasses completion';EXCEPTION WHEN check_violation THEN NULL;END;
 PERFORM pcs.staff_manage(auth,'CONCIERGE_MANAGER',true);
 r:=pcs.staff_workflow_action(auth,'service-phase',payload);replay:=pcs.staff_workflow_action(auth,'service-phase',payload);
 IF r->>'status'<>'SERVICE_IN_PROGRESS' OR replay->>'replayed'<>'true' THEN RAISE EXCEPTION 'QA start receipt missing';END IF;
 BEGIN PERFORM pcs.staff_workflow_action(auth,'service-phase',payload||'{"note":"Changed after committed request"}');RAISE EXCEPTION 'QA changed replay accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 IF (SELECT count(*) FROM public.audit_events WHERE entity_id=app::text AND action='service.execution.started')<>1 OR (SELECT count(*) FROM public.audit_events WHERE patch->>'application_id'=app::text AND action='staff.workflow.service-phase')<>1 THEN RAISE EXCEPTION 'QA execution audit repeated';END IF;
 BEGIN UPDATE public.applications SET qualification_data=qualification_data-'service_execution' WHERE id=app;RAISE EXCEPTION 'QA facts removed through editor';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE public.applications SET operational_status='CONFIRMED' WHERE id=app;RAISE EXCEPTION 'QA execution rewound through editor';EXCEPTION WHEN check_violation THEN NULL;END;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 PERFORM pcs.portal_admin_action('payment-instructions',jsonb_build_object('application_id',app,'expected_version',version,'instructions','QA bank instruction only'));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 r:=pcs.portal_action(client_hash,'payment',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'amount','400','reference','QA partial after start'));claim:=(r->>'claim_id')::uuid;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;SELECT updated_at::text INTO claim_version FROM pcs.application_payment_claims WHERE id=claim;
 PERFORM pcs.portal_admin_action('review-payment',jsonb_build_object('application_id',app,'expected_version',version,'claim_id',claim,'claim_version',claim_version,'decision','VERIFIED','note','QA operator bank verification'));
 UPDATE public.applications SET execution_issue_status='OPEN' WHERE id=app;SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 payload:=jsonb_build_object('application_id',app,'expected_version',version,'phase','COMPLETED','note','Synthetic operator checked completion','request_id',gen_random_uuid(),'confirmed','true');
 BEGIN PERFORM pcs.staff_workflow_action(auth,'service-phase',payload);RAISE EXCEPTION 'QA unresolved execution issue completed';EXCEPTION WHEN check_violation THEN NULL;END;
 UPDATE public.applications SET execution_issue_status='RESOLVED' WHERE id=app;SELECT updated_at::text INTO version FROM public.applications WHERE id=app;payload:=payload||jsonb_build_object('expected_version',version);
 r:=pcs.staff_workflow_action(auth,'service-phase',payload);IF r->>'status'<>'COMPLETED' OR (SELECT client_payment_status FROM public.applications WHERE id=app)<>'PARTIALLY_PAID' THEN RAISE EXCEPTION 'QA completion changes payment';END IF;
 IF (SELECT next_action_code FROM public.applications WHERE id=app)<>'VERIFY_FINAL_PAYMENT' THEN RAISE EXCEPTION 'QA unpaid completion lost payment step';END IF;
 INSERT INTO public.applications(public_id,category,item_id,operational_status,qualification_data) VALUES('QA-'||gen_random_uuid(),'booking',service,'CONFIRMED','{"start_date":"2117-01-10","end_date":"2117-01-12"}');
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 r:=pcs.portal_action(client_hash,'payment',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'amount','600','reference','QA final after completion'));claim:=(r->>'claim_id')::uuid;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;SELECT updated_at::text INTO claim_version FROM pcs.application_payment_claims WHERE id=claim;
 PERFORM pcs.portal_admin_action('review-payment',jsonb_build_object('application_id',app,'expected_version',version,'claim_id',claim,'claim_version',claim_version,'decision','VERIFIED','note','QA final bank verification'));
 IF (SELECT next_action_code FROM public.applications WHERE id=app)<>'ARCHIVE_COMPLETED_SERVICE' OR (SELECT operational_status FROM public.applications WHERE id=app)<>'COMPLETED' THEN RAISE EXCEPTION 'QA final payment reopens execution';END IF;
 -- Only saved future late-stage details are eligible; old completed details are not backfilled.
 UPDATE public.client_profiles SET source_contact_id=qa_contact WHERE id=client;
 INSERT INTO public.applications(id,public_id,category,client_profile_id,operational_status,client_payment_status,accepted_offer_snapshot) VALUES(late_app,'QA-'||late_app,'general',client,'COMPLETED','INSTRUCTIONS_SENT','{"client_price_thb":"1000","deposit_thb":"0"}');
 INSERT INTO pcs.application_payment_instructions(application_id,recipient,instructions,updated_at) VALUES(late_app,'PARTNER','QA future details','2000-01-01');
 EXECUTE $enqueue$__ENQUEUE__$enqueue$;
 IF EXISTS(SELECT 1 FROM public.pcs_workflow_outbox WHERE aggregate_id=late_app AND event_type='PAYMENT_INSTRUCTIONS_READY') THEN RAISE EXCEPTION 'QA old late-stage instructions backfilled';END IF;
 SELECT updated_at::text INTO version FROM pcs.application_payment_instructions WHERE application_id=late_app;
 EXECUTE $current$__CURRENT__$current$ INTO recorded USING late_app,client,version,qa_contact;GET DIAGNOSTICS n=ROW_COUNT;IF n<>0 THEN RAISE EXCEPTION 'QA old late-stage details can dispatch';END IF;
 UPDATE pcs.application_payment_instructions SET updated_at=clock_timestamp() WHERE application_id=late_app;
 EXECUTE $enqueue$__ENQUEUE__$enqueue$;
 IF NOT EXISTS(SELECT 1 FROM public.pcs_workflow_outbox WHERE aggregate_id=late_app AND event_type='PAYMENT_INSTRUCTIONS_READY') THEN RAISE EXCEPTION 'QA future late-stage details omitted';END IF;
 SELECT updated_at::text INTO version FROM pcs.application_payment_instructions WHERE application_id=late_app;
 EXECUTE $current$__CURRENT__$current$ INTO recorded USING late_app,client,version,qa_contact;GET DIAGNOSTICS n=ROW_COUNT;IF n<>1 THEN RAISE EXCEPTION 'QA future late-stage details cannot dispatch';END IF;
 UPDATE public.applications SET client_payment_status='PAID_TO_PARTNER' WHERE id=late_app;
 EXECUTE $current$__CURRENT__$current$ INTO recorded USING late_app,client,version,qa_contact;GET DIAGNOSTICS n=ROW_COUNT;IF n<>0 THEN RAISE EXCEPTION 'QA paid details can dispatch';END IF;
 PERFORM pcs.staff_manage(auth,'CONCIERGE_MANAGER',false);
 BEGIN PERFORM pcs.staff_workflow_action(auth,'service-phase',payload);RAISE EXCEPTION 'QA revoked staff can replay execution';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END;
